===== nginx.dockerfile =====
FROM node:24.16.0-slim AS intermediate

ARG FRONTEND_BUILD_MODE
ARG FRONTEND_VERSION

RUN apt-get update \
    && apt-get install -y --no-install-recommends \
        ca-certificates \
        curl \
        git \
    && rm -rf /var/lib/apt/lists/*

COPY ./ ./

RUN files/prebuild/write-version.sh
RUN files/prebuild/build-frontend.sh



# When upgrading:
#
# 1. Use full-length tag, including nginx version.  See:
#    * https://github.com/JonasAlfredsson/docker-nginx-certbot/blob/master/docs/dockerhub_tags.md
#    * https://hub.docker.com/r/jonasal/nginx-certbot/tags
# 2. Look for upstream changes to redirector.conf
# 3. Confirm setup-odk.sh strips out HTTP-01 ACME challenge location.
FROM jonasal/nginx-certbot:6.2.0-nginx1.31.2

EXPOSE 80
EXPOSE 443

# Persist Diffie-Hellman parameters and/or selfsign key
VOLUME [ "/etc/dh", "/etc/selfsign" ]

RUN apt-get update && apt-get install -y netcat-openbsd

RUN mkdir -p /usr/share/odk/nginx/

COPY files/nginx/setup-odk.sh \
     files/shared/envsub.awk \
     /scripts/

COPY files/nginx/redirector.conf /usr/share/odk/nginx/
COPY files/nginx/common-headers.conf /usr/share/odk/nginx/
COPY files/nginx/robots.txt /usr/share/nginx/html
COPY --from=intermediate dist/ /usr/share/nginx/html
COPY --from=intermediate /tmp/version.txt /usr/share/nginx/html

ENTRYPOINT [ "/scripts/setup-odk.sh" ]

===== odk.conf.template (structure) =====
1:server {
2:  listen 443 default_server ssl;
5:  ssl_certificate /etc/nginx/ssl/nginx.default.crt;
6:  ssl_certificate_key /etc/nginx/ssl/nginx.default.key;
108:    "default-src 'report-sample' 'none'; connect-src 'self' ${SENTRY_DSN_FRONTEND_ROOT} https://translate.google.com https://translate.googleapis.com; font-src 'self'; form-action 'self'; frame-ancestors 'none'; frame-src 'self' https://getodk.github.io/central/; img-src data: https:; manifest-src 'self'; media-src 'none'; object-src 'none'; script-src 'report-sample' 'self'; style-src 'report-sample' 'self'; style-src-attr 'unsafe-inline'; worker-src 'report-sample' blob:; report-uri /csp-report";
113:  ""      "default-src 'report-sample' 'none'; form-action 'none'; frame-ancestors 'none'; img-src http://${DOMAIN}/favicon.ico; report-uri /csp-report";
117:server {
118:  listen 443 ssl;
120:  server_name ${DOMAIN};
122:  ssl_certificate /etc/${SSL_TYPE}/live/${CERT_DOMAIN}/fullchain.pem;
123:  ssl_certificate_key /etc/${SSL_TYPE}/live/${CERT_DOMAIN}/privkey.pem;
124:  ssl_trusted_certificate /etc/${SSL_TYPE}/live/${CERT_DOMAIN}/fullchain.pem;
153:  location ~ "^/-/single/(?<enketoId>[a-zA-Z0-9]+)$" {
159:  location ~ "^/-/preview/(?<enketoId>[a-zA-Z0-9]+)$" {
166:  location ~ "^/-/(?!thanks$|connection$|login$|logout$|api$|preview$)(?<enketoId>[a-zA-Z0-9]+)$" {
172:  location = /-/single/check-submitted {
178:  location ~ ^/(?:-|enketo-passthrough)(?:/|$) {
184:    proxy_pass http://enketo:8005;
202:  location ~ ^/v\d {
209:    proxy_pass http://service:8383;
218:  location @blank.html {
219:    root /usr/share/nginx/html;
222:    add_header Content-Security-Policy "default-src 'report-sample' 'none'; connect-src https://translate.google.com https://translate.googleapis.com; form-action 'self'; frame-ancestors 'self'; img-src http://${DOMAIN}/favicon.ico https://translate.google.com; report-uri /csp-report" always;
225:  location = /blank.html {
230:  location / {
231:    root /usr/share/nginx/html;
239:  location /csp-report {
240:    proxy_pass https://${SENTRY_ORG_SUBDOMAIN}.ingest.sentry.io/api/${SENTRY_PROJECT}/security/?sentry_key=${SENTRY_KEY};
241:    proxy_ssl_server_name on;

