python3 - <<'PY'
import ast, pathlib
for charm in ("odk-central-k8s", "enketo-k8s", "pyxform-k8s"):
    deps = set()
    root = pathlib.Path("charms")/charm/"lib"
    for f in sorted(root.rglob("*.py")):
        if "odk_central_k8s" in str(f) or "pyxform_k8s" in str(f):
            continue
        try:
            tree = ast.parse(f.read_text())
        except SyntaxError:
            continue
        for node in tree.body:
            if isinstance(node, ast.Assign):
                for t in node.targets:
                    if isinstance(t, ast.Name) and t.id == "PYDEPS":
                        try:
                            deps.update(ast.literal_eval(node.value))
                        except Exception:
                            pass
    print(f"{charm}:")
    for d in sorted(deps):
        print("   ", d)
PY

