cd /home/ubuntu/odk-central-operators
juju ssh --container enketo enketo-k8s/0 "EXPORTER_PORT=9198 timeout 22 node /tmp/ee.js & sleep 10; node -e \"
const http=require('http');
http.get('http://localhost:9198/metrics',r=>{let b='';r.on('data',d=>b+=d);r.on('end',()=>console.log(b));}).on('error',e=>console.log('ERR',e.message));
\"; sleep 2" 2>&1 | grep -vE '^#' | grep -E 'enketo_' | head -14

